# Collect all song IDs from song library, album library, and playlist library
song_ids = set()

# From song library
for song in song_library:
    song_ids.add(song['song_id'])

# From album library
for album in album_library:
    for sid in album['song_ids']:
        song_ids.add(sid)

# From playlist library
for pl in playlist_library:
    for sid in pl['song_ids']:
        song_ids.add(sid)

print(f"Total unique song IDs: {len(song_ids)}")
print(sorted(song_ids))

